CREATE OR REPLACE FUNCTION public.setup_household(_name text, _code text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h uuid; n text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF public.my_household() IS NOT NULL THEN RAISE EXCEPTION 'Already in a household'; END IF; n:=trim(_name); IF length(n)<1 OR length(n)>60 THEN RAISE EXCEPTION 'Enter a name (1–60 characters)'; END IF; IF _code IS NOT NULL THEN SELECT id INTO h FROM public.households WHERE invite_code=trim(_code) FOR UPDATE; IF h IS NULL THEN RAISE EXCEPTION 'Invalid invite code'; END IF; IF (SELECT count(*) FROM public.household_members WHERE household_id=h)>=12 THEN RAISE EXCEPTION 'This household is full (12 members)'; END IF; ELSE INSERT INTO public.households DEFAULT VALUES RETURNING id INTO h; END IF; INSERT INTO public.household_members VALUES(auth.uid(),h,n); UPDATE public.profiles SET display_name=n WHERE id=auth.uid(); IF _code IS NULL THEN INSERT INTO public.pantry_items(household_id,name,category,emoji,shelf_life) VALUES(h,'Eggs','Dairy & Eggs','🥚',21),(h,'Milk','Dairy & Eggs','🥛',7),(h,'Bread','Bakery','🍞',5),(h,'Bananas','Produce','🍌',5),(h,'Tomatoes','Produce','🍅',7),(h,'Onions','Produce','🧅',30),(h,'Chicken','Meat & Protein','🍗',3),(h,'Rice','Pantry','🍚',60),(h,'Coffee','Drinks','☕',60),(h,'Cheese','Dairy & Eggs','🧀',14),(h,'Toilet paper','Household & Cleaning','🧻',30),(h,'Dish soap','Household & Cleaning','🧴',45),(h,'Cat food','Pet supplies','🐱',30); END IF; RETURN h; END $$;
ALTER TABLE public.pantry_items ADD COLUMN requested_by uuid;
CREATE FUNCTION public.stamp_requester() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.on_list AND (TG_OP='INSERT' OR NOT OLD.on_list) THEN NEW.requested_by:=auth.uid(); ELSIF TG_OP='UPDATE' THEN NEW.requested_by:=OLD.requested_by; END IF; IF TG_OP='INSERT' AND NOT NEW.on_list THEN NEW.requested_by:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER stamp_requester BEFORE INSERT OR UPDATE ON public.pantry_items FOR EACH ROW EXECUTE FUNCTION public.stamp_requester();